pub struct RingBuffer {
    buf: [u64; 64],
    head: usize,
    tail: usize,
    len: usize,
}

impl RingBuffer {
    pub const fn new() -> Self {
        Self { buf: [0; 64], head: 0, tail: 0, len: 0 }
    }
    pub fn push(&mut self, val: u64) -> bool {
        if self.len == 64 { return false; }
        self.buf[self.tail] = val;
        self.tail = (self.tail + 1) % 64;
        self.len += 1;
        true
    }
    pub fn pop(&mut self) -> Option<u64> {
        if self.len == 0 { return None; }
        let val = self.buf[self.head];
        self.head = (self.head + 1) % 64;
        self.len -= 1;
        Some(val)
    }
}

