int xdp_filter(struct xdp_md *ctx) {
    void *data = (void *)(long)ctx->data;
    void *data_end = (void *)(long)ctx->data_end;
    struct ethhdr *eth = data;
    if ((void *)(eth + 1) > data_end) return XDP_PASS;
    if (eth->h_proto != __constant_htons(ETH_P_IP)) return XDP_PASS;
    struct iphdr *ip = (void *)(eth + 1);
    if ((void *)(ip + 1) > data_end) return XDP_PASS;
    if (ip->protocol == IPPROTO_UDP) {
        struct udphdr *udp = (void *)(ip + 1);
        if ((void *)(udp + 1) > data_end) return XDP_PASS;
        __u16 dport = __constant_ntohs(udp->dest);
        if ((dport == 53 || dport == 123) && (data_end - data > 512)) return XDP_DROP;
    }
    return XDP_PASS;
}

server {
    listen 443 ssl http2;
    server_name xavuntu.internal;
    ssl_certificate /etc/ssl/certs/xavuntu.crt;
    ssl_certificate_key /etc/ssl/private/xavuntu.key;
    ssl_protocols TLSv1.3;
    ssl_prefer_server_ciphers off;
    add_header X-Content-Type-Options nosniff;
    add_header X-Frame-Options DENY;
    add_header Strict-Transport-Security "max-age=31536000; includeSubDomains" always;
    location / {
        proxy_pass http://127.0.0.1:5000;
        proxy_set_header Host $host;
        proxy_set_header X-Real-IP $remote_addr;
    }
}
